diff --git a/mame-source/src/devices/cpu/mcs96/mcs96ops.lst b/mame-source/src/devices/cpu/mcs96/mcs96ops.lst
index 4704103c..246ebb6a 100644
--- a/mame-source/src/devices/cpu/mcs96/mcs96ops.lst
+++ b/mame-source/src/devices/cpu/mcs96/mcs96ops.lst
@@ -1944,28 +1944,29 @@ f7    trap  none

 f8    clrc  none
 	PSW &= ~F_C;
-	next(4);
+	// Intel 80C196KB Table 3-3B: two states; retain legacy 8097 timing.
+	next(m_kb_mode ? 2 : 4);

 f9    setc  none
 	PSW |= F_C;
-	next(4);
+	next(m_kb_mode ? 2 : 4);

 fa    di    none
 	PSW &= ~F_I;
 	check_irq();
-	next_noirq(4);
+	next_noirq(m_kb_mode ? 2 : 4);

 fb    ei    none
 	PSW |= F_I;
 	check_irq();
-	next_noirq(4);
+	next_noirq(m_kb_mode ? 2 : 4);

 fc    clrvt none
 	PSW &= ~F_VT;
-	next(4);
+	next(m_kb_mode ? 2 : 4);

 fd    nop   none
-	next(4);
+	next(m_kb_mode ? 2 : 4);

 ff    rst   none
 	PC = 0x2080;
